{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The closest structural analogue, ginsenoside Rg3, showed low oral bioavailability in a human pharmacokinetic study; the query is a more heavily glycosylated protopanaxadiol ginsenoside, so this directly supports a low F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Glycyrrhizin, a triterpenoid saponin with multiple sugar moieties, has an absolute oral bioavailability of approximately 0.25% in humans, demonstrating that this glycosylated saponin class is very poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Astragaloside IV, a glycosylated triterpenoid saponin, has poor oral bioavailability in humans due to very low solubility in biological fluids, supporting the same liability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Avenacosides, steroidal glycosides from oats, exhibited low oral bioavailability in human participants, consistent with poor absorption of complex glycosylated natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Naringin, a flavonoid glycoside, has an oral bioavailability of only about 5–9% in humans, below the 20% threshold and consistent with the poor absorption expected for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Oleanolic acid, a triterpenoid aglycone, showed poor oral bioavailability in healthy volunteers; the additional sugar chains in the query would be expected to further reduce absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a heavily glycosylated protopanaxadiol ginsenoside. The closest analogue Rg3 has low human oral bioavailability, and multiple glycosylated triterpenoid saponins consistently show very low oral absorption. The additional sugar chains in the query are expected to further decrease permeability and oral bioavailability, so F is predicted to be below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "The closest analogue record reports low bioavailability but not an exact absolute F value.",
    "Most saponin bioavailability studies measure the parent compound, which may not capture systemic exposure of active metabolites."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

